def transform(grid):
    # Motif colors appear on parallel descending diagonals. Complete the
    # field by extending each colored diagonal stripe across the grid.
    h, w = len(grid), max(len(row) for row in grid)
    # Use c-r diagonal offset; preserve the stripe color wherever observed.
    stripe = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                stripe.setdefault(c-r, color)
    # Nearest colored diagonal determines each cell's stripe, with cyclic
    # continuation of the observed diagonal ordering.
    keys = sorted(stripe)
    if not keys:
        return [row[:] for row in grid]
    period = max(1, len(keys))
    vals = [stripe[k] for k in keys]
    base = keys[0]
    return [[vals[(c-r-base) % period] for c in range(w)] for r in range(h)]


def check(pairs):
    return all(transform(inp) == out for inp, out in pairs)
