def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [[bg for _ in range(w)] for _ in range(h)]
    seen = set()
    candidates = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            rs = [p[0] for p in cells]; cs = [p[1] for p in cells]
            r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
            area = (r1-r0+1)*(c1-c0+1)
            # A valid object is a nearly complete, at least 2x2 rectangle;
            # other colors inside its bounds are treated as corruption.
            if r1 > r0 and c1 > c0 and len(cells) / area >= 0.62:
                candidates.append((r0,r1,c0,c1,color,len(cells)/area))
    # Prefer the broadest coherent rectangle where components overlap.
    for r0,r1,c0,c1,color,density in sorted(candidates, key=lambda x: (x[5], (x[1]-x[0]+1)*(x[3]-x[2]+1)), reverse=True):
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                out[r][c] = color
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
