                continue
            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
            if (r1 - r0 + 1) * (c1 - c0 + 1) != len(cells):
                continue
            for y, x in cells:
                out[y][x] = color
    return out


if __name__ == '__main__':
