 "content": "from collections import Counter


def transform(grid):
    h = len(grid)
    widths = [len(row) for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg] * n for n in widths]
    seen = set()
    for r in range(h):
        for c in range(widths[r]):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < widths[yy] and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            rs = [y for y,x in cells]
            cs = [x for y,x in cells]
            r0,r1,c0,c1 = min(rs),max(rs),min(cs),max(cs)
            area = (r1-r0+1)*(c1-c0+1)
            # Restore substantial rectangular colored regions; isolated specks
